statement: -- ═══════════════════════════════════════════════════════════════════════════════
-- 703_fix_conversation_rls_recursion.sql
-- ═══════════════════════════════════════════════════════════════════════════════
-- Breaks the RLS recursion on ConversationParticipant (and its dependents,
-- Message and Conversation) by moving the membership check into a
-- SECURITY DEFINER helper that bypasses RLS.
--
-- Idempotent. Safe to re-run.
-- ═══════════════════════════════════════════════════════════════════════════════

BEGIN;
SET LOCAL statement_timeout = '2min';
SET LOCAL lock_timeout = '20s';

-- ─── §1. Drop every policy that touches ConversationParticipant ──────────────
DROP POLICY IF EXISTS participant_self_read        ON public."ConversationParticipant";
DROP POLICY IF EXISTS message_participant_read     ON public."Message";
DROP POLICY IF EXISTS message_participant_send     ON public."Message";
DROP POLICY IF EXISTS conversation_participant_read ON public."Conversation";

-- ─── §2. SECURITY DEFINER helper ────────────────────────────────────────────
-- Runs as the function owner (postgres). Bypasses RLS on ConversationParticipant
-- so the inner SELECT no longer re-enters the policy.
CREATE OR REPLACE FUNCTION public.user_is_in_conversation(p_conversation_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public."ConversationParticipant"
    WHERE "conversationId" = p_conversation_id
      AND "userId" = (SELECT auth.uid())
  );
$$;

-- Never callable by anon. Only authenticated users.
REVOKE ALL ON FUNCTION public.user_is_in_conversation(uuid) FROM anon, PUBLIC;
GRANT EXECUTE ON FUNCTION public.user_is_in_conversation(uuid) TO authenticated;

-- ─── §3. Rewrite policies to call the helper ────────────────────────────────

-- Conversation: participants read conversations they belong to
CREATE POLICY conversation_participant_read ON public."Conversation"
  FOR SELECT TO authenticated
  USING (public.user_is_in_conversation("Conversation".id));

-- ConversationParticipant: user sees their own row OR any row in a conversation
-- they belong to. The second clause is now recursion-free.
CREATE POLICY participant_self_read ON public."ConversationParticipant"
  FOR SELECT TO authenticated
  USING (
    "userId" = (SELECT auth.uid())
    OR public.user_is_in_conversation("ConversationParticipant"."conversationId")
  );

-- Message: participants read all messages in their conversations
CREATE POLICY message_participant_read ON public."Message"
  FOR SELECT TO authenticated
  USING (public.user_is_in_conversation("Message"."conversationId"));

-- Message: sender must be the authenticated user AND a participant
CREATE POLICY message_participant_send ON public."Message"
  FOR INSERT TO authenticated
  WITH CHECK (
    "senderId" = (SELECT auth.uid())
    AND public.user_is_in_conversation("Message"."conversationId")
  );

-- ─── §4. Verify ─────────────────────────────────────────────────────────────
DO $verify$
DECLARE
  v_helper_ok   boolean;
  v_anon_can    boolean;
  v_auth_can    boolean;
  v_policies    int;
BEGIN
  v_helper_ok := EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname = 'user_is_in_conversation'
      AND p.prosecdef = true
  );

  v_anon_can := has_function_privilege(
    'anon', 'public.user_is_in_conversation(uuid)', 'EXECUTE'
  );
  v_auth_can := has_function_privilege(
    'authenticated', 'public.user_is_in_conversation(uuid)', 'EXECUTE'
  );

  SELECT COUNT(*) INTO v_policies
  FROM pg_policies
  WHERE schemaname = 'public'
    AND policyname IN (
      'conversation_participant_read',
      'participant_self_read',
      'message_participant_read',
      'message_participant_send'
    );

  RAISE NOTICE '';
  RAISE NOTICE '═══════════════════════════════════════════════════════════════';
  RAISE NOTICE '  703_fix_conversation_rls_recursion.sql — VERIFIED';
  RAISE NOTICE '  helper exists + SECURITY DEFINER : %', v_helper_ok;
  RAISE NOTICE '  anon can call helper             : %  (target: false)', v_anon_can;
  RAISE NOTICE '  authenticated can call helper    : %  (target: true)', v_auth_can;
  RAISE NOTICE '  policies rewritten               : %  (target: 4)', v_policies;
  RAISE NOTICE '═══════════════════════════════════════════════════════════════';

  IF NOT v_helper_ok OR v_anon_can OR NOT v_auth_can OR v_policies <> 4 THEN
    RAISE EXCEPTION '703 verification failed';
  END IF;
  RAISE NOTICE '  ✓ ALL CHECKS PASSED';
  RAISE NOTICE '═══════════════════════════════════════════════════════════════';
END $verify$;

NOTIFY pgrst, 'reload schema';
NOTIFY pgrst, 'reload config';
COMMIT;

