AUDIT: SESSION,1,1,DDL,CREATE FUNCTION,FUNCTION,pg_temp_48.count_estimate(pg_catalog.text),"CREATE OR REPLACE FUNCTION pg_temp.count_estimate(
    query text
) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    plan jsonb;
BEGIN
    EXECUTE 'EXPLAIN (FORMAT JSON)' || query INTO plan;
    RETURN plan->0->'Plan'->'Plan Rows';
END;
$$",<not logged>

statement: SET statement_timeout='58s'; SET idle_session_timeout='58s';
CREATE OR REPLACE FUNCTION pg_temp.count_estimate(
    query text
) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    plan jsonb;
BEGIN
    EXECUTE 'EXPLAIN (FORMAT JSON)' || query INTO plan;
    RETURN plan->0->'Plan'->'Plan Rows';
END;
$$;


with approximation as (select reltuples as estimate from pg_class where oid = 'auth.users'::regclass)
select 
  case 
    when estimate = -1 then (select pg_temp.count_estimate('select * from auth.users'))::int
    when estimate > 50000 then estimate::int
    else (select count(*) from auth.users)
  end as count,
  estimate = -1 or estimate > 50000 as is_estimate
from approximation

